import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)

    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = [list(neighbors) for neighbors in adj]

    # Compute degrees for each vertex
    degrees = [len(adj_list[i]) for i in range(n)]

    # Handle trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in degrees):
        return [0] * n

    # Helper: greedy coloring given an order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Kempe chain swap for colors a and b, starting from vertex v
    def kempe_swap(coloring, a, b, v):
        stack = [v]
        visited = set([v])
        component = set()
        while stack:
            node = stack.pop()
            component.add(node)
            for u in adj_list[node]:
                if coloring[u] == a or coloring[u] == b:
                    if u not in visited:
                        visited.add(u)
                        stack.append(u)
        for node in component:
            if coloring[node] == a:
                coloring[node] = b
            elif coloring[node] == b:
                coloring[node] = a
        return coloring

    # Helper: Kempe chain improvement (iterative, targets highest color class)
    def kempe_improve(coloring):
        if n == 0:
            return coloring
        max_color = max(coloring)
        if max_color <= 0:
            return coloring
        while True:
            made_progress = False
            # Process from highest color down to 1
            for target_color in range(max_color, 0, -1):
                color_class = [v for v in range(n) if coloring[v] == target_color]
                if not color_class:
                    continue
                for v in color_class:
                    if coloring[v] != target_color:
                        continue
                    # Try direct reassignment to a lower color
                    neighbor_colors = set()
                    for u in adj_list[v]:
                        if coloring[u] != -1:
                            neighbor_colors.add(coloring[u])
                    for c in range(target_color):
                        if c not in neighbor_colors:
                            coloring[v] = c
                            made_progress = True
                            break
                    if coloring[v] != target_color:
                        continue
                    # Try Kempe chain swaps for each lower color
                    for c in range(target_color):
                        if c in neighbor_colors:
                            continue
                        # Build Kempe chain component for (c, target_color) containing v
                        stack = [v]
                        visited = set([v])
                        while stack:
                            node = stack.pop()
                            for u in adj_list[node]:
                                if coloring[u] == c or coloring[u] == target_color:
                                    if u not in visited:
                                        visited.add(u)
                                        stack.append(u)
                        # Check conflict: neighbor of v in component with color target_color (other than v)
                        conflict = False
                        for u in adj_list[v]:
                            if u != v and u in visited and coloring[u] == target_color:
                                conflict = True
                                break
                        if not conflict:
                            kempe_swap(coloring, c, target_color, v)
                            made_progress = True
                            break
                    if coloring[v] != target_color:
                        break
                if made_progress:
                    break
            if not made_progress:
                break
            max_color = max(coloring)
            if max_color <= 0:
                break
        return coloring

