            candidates_v = []
            for v in uncolored:
                sat_deg = len(saturation[v])
                if sat_deg > max_sat:
                    max_sat = sat_deg
                    candidates_v = [v]
                elif sat_deg == max_sat:
                    candidates_v.append(v)

            if len(candidates_v) > 1:
                max_deg = -1
                new_candidates = []
                for v in candidates_v:
                    deg = uncolored_degree(v)
                    if deg > max_deg or (deg == max_deg and v < (new_candidates[0] if new_candidates else -1)):
                        max_deg = deg
                        new_candidates = [v]
                    elif deg == max_deg and v == (new_candidates[0] if new_candidates else -1):
                        new_candidates.append(v)
                candidates_v = new_candidates

            v = min(candidates_v)  # Deterministic: choose smallest index
            used = saturation[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    saturation[u].add(c)

        return color[:], max(color) + 1 if n > 0 else 0

    # Helper: RLF (Recursive Largest First) with optimized data structures and deterministic tie-breaking
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Vertex with max degree in uncolored subgraph, break ties by index
            v = max(uncolored, key=lambda x: (sum(1 for u in adj_list[x] if u in uncolored), x))
            S = {v}
            U = set()
            W = set()
            for u in uncolored:
                if u == v:
                    continue
                adjacent = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)

            while U:
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    w_count = sum(1 for nb in adj_list[u] if nb in W)
                    deg_in_U = sum(1 for nb in adj_list[u] if nb in U)
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_count == max_w_neighbors and deg_in_U == min_deg_in_U and u < (best_u if best_u is not None else n)):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                S.add(best_u)
                U.remove(best_u)
                for nb in adj_list[best_u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)

            for node in S:
                color[node] = current_color
                uncolored.remove(node)
            current_color += 1

        return color[:], max(color) + 1 if n > 0 else 0

    # Helper: Smallest-Last ordering (Matula & Beck) with bucket sort for O(N+E) and deterministic tie-breaking
    def smallest_last():
        remaining = set(range(n))
        degree_copy = degrees[:]
        order = []
        max_deg = max(degrees) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree_copy[v]
            if d < len(buckets):
                buckets[d].add(v)
            else:
                while len(buckets) <= d:
                    buckets.append(set())
                buckets[d].add(v)

        for _ in range(n):
            d = 0
            while d < len(buckets) and not buckets[d]:
                d += 1
            if d >= len(buckets):
                break
            v = min(buckets[d])  # Deterministic: smallest index
            buckets[d].remove(v)
            order.append(v)
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = degree_copy[u]
                    if old_deg < len(buckets) and u in buckets[old_deg]:
                        buckets[old_deg].remove(u)
                    degree_copy[u] -= 1
                    new_deg = degree_copy[u]
                    if new_deg < len(buckets):
                        buckets[new_deg].add(u)
                    else:
                        while len(buckets) <= new_deg:
                            buckets.append(set())
                        buckets[new_deg].add(u)
            remaining.remove(v)

        color = greedy_color(list(reversed(order)))
        return color[:], max(color) + 1 if n > 0 else 0

    # Helper: Welsh-Powell (degree descending) with deterministic tie-breaking
    def welsh_powell():
        order = sorted(range(n), key=lambda x: (len(adj_list[x]), -x), reverse=True)  # Higher degree first, then lower index for tie
        color = greedy_color(order)
        return color[:], max(color) + 1 if n > 0 else 0

    # Construct initial solutions using multiple heuristics
    candidates = []

    # 1. DSATUR
    candidates.append(dsatur())

    # 2. RLF
    candidates.append(rlf())

    # 3. Smallest-Last ordering
    candidates.append(smallest_last())

    # 4. Welsh-Powell
    candidates.append(welsh_powell())

    # Select the best initial coloring (fewest colors, then lexicographically smallest)
    best_coloring, best_k = min(candidates, key=lambda x: (x[1], x[0]))

